"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { AlertTriangle, ArrowDown, ArrowUp, Check, Download, FileUp, FilterX, FolderTree, ListFilter, LoaderCircle, Plus, RefreshCw, Search, Trash2, Upload, X } from "lucide-react";
import { AMParametersNormalizationPanel } from "./AMParametersNormalizationPanel";
import { AMCatalogueLayerSearch } from "./AMCatalogueLayerSearch";
import { useUiText } from "@/lib/ui-i18n";
import { V3InfoTip } from "@/components/rag-v3/V3Tooltip";

type Parameter = { technical_name: string; ui_element: string; category?: string; sub_category?: string; name_ru?: string; description_en?: string; description_ru?: string; domain?: string; semantic_keywords?: string[]; lyria_prompt_tags?: string[]; _catalogue?: { source: string; completeness: number; missing_fields: string[] }; queued?: boolean; [key: string]: unknown };
type CompletionRow = Parameter & { _completion: { completeness: number; missing_count: number; missing_fields: string[] } };
type QueueItem = { id: string; operation: string; technical_name: string; payload?: Parameter; previous?: Parameter; status: string; reason?: string; error?: string; created_at: string };
const tabs = [["catalog", "Каталог"], ["layer-search", "Слои / Layer search"], ["categories", "По категориям"], ["gaps", "Пробелы"], ["completeness", "Полнота"], ["normalization", "Нормализация"], ["queue", "Очередь"], ["exchange", "Импорт / экспорт"], ["status", "Статус индексов"]] as const;
const inputClass = "h-9 rounded-md border border-white/10 bg-black/30 px-3 text-sm text-foreground outline-none focus:border-primary/60";

export function AMParametersCataloguePage() {
  const t = useUiText();
  const [tab, setTab] = useState<(typeof tabs)[number][0]>("catalog");
  const [query, setQuery] = useState(""); const [debouncedQuery, setDebouncedQuery] = useState("");
  const [rows, setRows] = useState<Parameter[]>([]); const [total, setTotal] = useState(0); const [page, setPage] = useState(1); const pageSize = 50;
  const [categories, setCategories] = useState<Array<{ category: string; count: number; subcategories: Array<{ sub_category: string; count: number }> }>>([]);
  const [category, setCategory] = useState(""); const [subCategory, setSubCategory] = useState(""); const [domain, setDomain] = useState(""); const [completeness, setCompleteness] = useState("all"); const [presence, setPresence] = useState("all"); const [source, setSource] = useState("all"); const [sort, setSort] = useState("category"); const [direction, setDirection] = useState("asc");
  const [selected, setSelected] = useState<string[]>([]); const [typeFilter, setTypeFilter] = useState(""); const [queue, setQueue] = useState<QueueItem[]>([]); const [gaps, setGaps] = useState<{ incomplete: Parameter[]; uncategorized: Parameter[]; sparse_categories: Array<{ category: string; sub_category: string | null; count: number; sparse_limit: number }> }>({ incomplete: [], uncategorized: [], sparse_categories: [] });
  const [status, setStatus] = useState<Record<string, unknown>>({}); const [editor, setEditor] = useState<{ mode: "add" | "edit"; parameter: Parameter; queueId?: string } | null>(null); const [editorText, setEditorText] = useState(""); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState(""); const [gapSort, setGapSort] = useState("technical_name"); const [gapScope, setGapScope] = useState<"incomplete" | "uncategorized">("incomplete"); const [duplicateMode, setDuplicateMode] = useState("stage-update");
  const [normalization, setNormalization] = useState<Record<string, unknown>>({}); const [confidenceThreshold, setConfidenceThreshold] = useState(0.6); const [batchSize, setBatchSize] = useState(25); const [fillBatchSize, setFillBatchSize] = useState(10); const [autoApply, setAutoApply] = useState(true); const [forceDomain, setForceDomain] = useState(false); const [forceEnrichment, setForceEnrichment] = useState(false);

  useEffect(() => { const stored = Number(window.localStorage.getItem("am-catalogue-fill-batch-size")); if (Number.isFinite(stored) && stored >= 1 && stored <= 50) window.setTimeout(() => setFillBatchSize(stored), 0); }, []);
  useEffect(() => { window.localStorage.setItem("am-catalogue-fill-batch-size", String(fillBatchSize)); }, [fillBatchSize]);
  useEffect(() => { const timer = window.setTimeout(() => { setDebouncedQuery(query); setPage(1); }, 250); return () => window.clearTimeout(timer); }, [query]);
  const loadRows = useCallback(async () => {
    const params = new URLSearchParams({ q: debouncedQuery, page: String(page), page_size: String(pageSize), sort, direction, completeness, category_presence: presence, source });
    if (typeFilter) params.set("type", typeFilter); if (category) params.append("category", category); if (subCategory) params.append("sub_category", subCategory); if (domain) params.append("domain", domain);
    const response = await fetch(`/api/am-parameters-catalogue/parameters?${params}`); const data = await response.json(); if (response.ok) { setRows(data.parameters); setTotal(data.total); }
  }, [debouncedQuery, page, sort, direction, completeness, presence, source, category, subCategory, domain, typeFilter]);
  const loadQueue = useCallback(async () => { const response = await fetch("/api/am-parameters-catalogue/queue"); const data = await response.json(); if (response.ok) setQueue(data.items); }, []);
  const loadStatus = useCallback(async () => { const response = await fetch("/api/am-parameters-catalogue/status"); const data = await response.json(); if (response.ok) setStatus(data); }, []);
  const loadNormalization = useCallback(async () => { const response = await fetch("/api/am-parameters-catalogue/normalization/status"); const data = await response.json(); if (response.ok) setNormalization(data); }, []);
  const loadBase = useCallback(async () => {
    const [categoryResponse, gapResponse] = await Promise.all([fetch("/api/am-parameters-catalogue/categories"), fetch("/api/am-parameters-catalogue/gaps")]);
    const categoryData = await categoryResponse.json(); const gapData = await gapResponse.json();
    if (categoryResponse.ok) setCategories(categoryData.categories); if (gapResponse.ok) setGaps(gapData);
  }, []);
  useEffect(() => { const timer = window.setTimeout(() => { void loadRows(); }, 0); return () => window.clearTimeout(timer); }, [loadRows]);
  useEffect(() => { const timer = window.setTimeout(() => { void loadBase(); void loadQueue(); void loadStatus(); void loadNormalization(); }, 0); return () => window.clearTimeout(timer); }, [loadBase, loadQueue, loadStatus, loadNormalization]);
  useEffect(() => { if (status.job && (status.job as { running?: boolean }).running) { const timer = window.setInterval(() => { void loadStatus(); }, 2000); return () => window.clearInterval(timer); } }, [status.job, loadStatus]);
  const normalizationJob = normalization.current_job as { id?: string; phase?: string; status?: string; step?: string; rows_scanned?: number; changed?: number; skipped?: number; failed?: number; error?: string; log_tail?: string[]; queue_ids?: string[] } | null;
  useEffect(() => { if (normalizationJob?.status === "running") { const timer = window.setInterval(() => { void loadNormalization(); }, 1500); return () => window.clearInterval(timer); } }, [normalizationJob?.id, normalizationJob?.status, loadNormalization]);

  const refresh = async () => { setBusy(true); try { await Promise.all([loadRows(), loadBase(), loadQueue(), loadStatus(), loadNormalization()]); } finally { setBusy(false); } };
  const runNormalization = async (phase: string) => {
    if (phase === "all" && !window.confirm("Запустить полный конвейер A→E? Категории и описания будут классифицированы LLM, изменения автоматически попадут в очередь и при включённом автоприменении будут сохранены с резервной копией. Построчное подтверждение не потребуется.")) return;
    setNormalization((current) => ({ ...current, current_job: { id: "starting", phase, status: "running", step: "Запуск", rows_scanned: 0, changed: 0, skipped: 0, failed: 0, log_tail: [] } }));
    setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/normalization/run", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ phase, options: { apply: autoApply, rebuild: false, forceDomain, forceEnrichment, confidenceThreshold, batchSize } }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error); setNotice(`Задание «${phase}» запущено.`); await Promise.all([loadNormalization(), loadQueue()]); } catch (error) { setNotice(error instanceof Error ? error.message : "Не удалось запустить нормализацию."); } finally { setBusy(false); }
  };
  const beginEdit = (parameter: Parameter) => { const clean = { ...parameter }; delete clean._catalogue; delete clean.queued; setEditor({ mode: "edit", parameter }); setEditorText(JSON.stringify(clean, null, 2)); };
  const beginAdd = () => { setEditor({ mode: "add", parameter: { technical_name: "", ui_element: "Range" } }); setEditorText(JSON.stringify({ technical_name: "", ui_element: "Range", name_ru: "", description_en: "", description_ru: "", category: "", sub_category: "", min_value: 0, max_value: 1, default: 0.5, step: 0.01, unit: "", semantic_keywords: [], lyria_prompt_tags: [] }, null, 2)); };
  const submitEdit = async () => {
    try {
      const parameter = JSON.parse(editorText) as Parameter; setBusy(true);
      const response = editor?.queueId ? await fetch("/api/am-parameters-catalogue/queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "edit", ids: [editor.queueId], payload: parameter }) }) : editor?.mode === "add" ? await fetch("/api/am-parameters-catalogue/queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ operation: "add", payload: parameter }) }) : await fetch(`/api/am-parameters-catalogue/parameters/${encodeURIComponent(editor!.parameter.technical_name)}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(parameter) });
      const data = await response.json(); if (!response.ok) throw new Error(data.error); setEditor(null); setNotice("Изменение добавлено в очередь."); await Promise.all([loadRows(), loadQueue()]);
    } catch (error) { setNotice(error instanceof Error ? error.message : "Проверьте JSON."); } finally { setBusy(false); }
  };
  const stageDelete = async (names: string[]) => {
    const confirmed = window.confirm(`Поставить в очередь физическое удаление ${names.length} параметров? Удаление применится только после Commit & Rebuild.`); if (!confirmed) return;
    const response = await fetch("/api/am-parameters-catalogue/queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ operation: "delete", technical_names: names, reason: "Удаление из каталога" }) }); const data = await response.json(); setNotice(response.ok ? `В очередь добавлено: ${data.staged}.` : data.error); setSelected([]); await Promise.all([loadRows(), loadQueue()]);
  };
  const toggleAll = () => setSelected(selected.length === rows.length ? [] : rows.map((row) => row.technical_name));
  const toggleSort = (field: string) => { if (sort === field) setDirection(direction === "asc" ? "desc" : "asc"); else { setSort(field); setDirection("asc"); } };
  const resetFilters = () => { setCategory(""); setSubCategory(""); setDomain(""); setTypeFilter(""); setCompleteness("all"); setPresence("all"); setSource("all"); setQuery(""); setPage(1); };
  const gapRows = gapScope === "incomplete" ? gaps.incomplete : gaps.uncategorized;
  const filteredGapRows = useMemo(() => gapRows.filter((row) => !debouncedQuery || [row.technical_name, row.name_ru, row.category, row.sub_category, row.description_ru].join(" ").toLocaleLowerCase().includes(debouncedQuery.toLocaleLowerCase())).sort((a, b) => String(a[gapSort] ?? "").localeCompare(String(b[gapSort] ?? ""))), [gapRows, debouncedQuery, gapSort]);
  const commit = async () => { const actionable = queue.filter((item) => item.status === "pending" || item.status === "applying" || item.status === "failed"); if (!actionable.length) return; const counts = { add: actionable.filter((item) => item.operation === "add").length, update: actionable.filter((item) => item.operation === "update").length, delete: actionable.filter((item) => item.operation === "delete").length }; const confirmed = window.confirm(`Подтвердить commit очереди?\nДобавления: ${counts.add}\nОбновления: ${counts.update}\nУдаления: ${counts.delete}\n\nПеред записью будет создана резервная копия. Индексы будут помечены устаревшими; embedding rebuild не запускается.`); if (!confirmed) return; setBusy(true); setNotice("Commit: резервное копирование и запись изменений…"); try { const response = await fetch("/api/am-parameters-catalogue/queue/commit", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ confirmed: true, rebuild: false }) }); const data = await response.json(); if (!response.ok) throw new Error(data.error ?? `HTTP ${response.status}`); setNotice(`Применено: ${data.changed}; пропущено: ${data.skipped_count ?? 0}; ошибок в очереди: ${data.failed_count ?? 0}. Backup: ${data.backup_path ?? data.backup}; очередь: ${data.queue_backup_path ?? "—"}. Индексы помечены устаревшими, перестройка не запускалась.`); await refresh(); } catch (error) { setNotice(error instanceof Error ? error.message : "Не удалось применить очередь."); } finally { setBusy(false); } };
  const exportFile = async (format: string, names?: string[]) => { setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ format, technical_names: names, query: names ? undefined : debouncedQuery, category: category ? [category] : undefined, sub_category: subCategory ? [subCategory] : undefined, domain: domain || undefined, completeness, category_presence: presence, source }) }); if (!response.ok) { const data = await response.json(); throw new Error(data.error); } const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = format === "zip" ? "am-parameters-catalogue.zip" : `am-parameters-catalogue.${format}`; link.click(); URL.revokeObjectURL(url); } catch (error) { setNotice(error instanceof Error ? error.message : "Ошибка экспорта."); } finally { setBusy(false); } };
  const importFile = async (file?: File) => { if (!file) return; const form = new FormData(); form.set("file", file); form.set("duplicate_mode", duplicateMode); setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/import", { method: "POST", body: form }); const data = await response.json(); setNotice(response.ok ? `Импорт завершён: в очередь ${data.accepted}, отклонено ${data.rejected}, конфликтов ${data.conflicts}.` : data.error); await Promise.all([loadQueue(), loadRows()]); } finally { setBusy(false); } };
  const rebuildIndexes = async () => { if (!window.confirm("Запустить пересборку составного индекса и live anchors из опубликованной библиотеки?")) return; setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/indexes/rebuild", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ confirmed: true }) }); const data = await response.json(); setNotice(response.ok ? "Пересборка запущена." : data.error); await loadStatus(); } finally { setBusy(false); } };
  const discardQueue = async (id: string) => { await fetch("/api/am-parameters-catalogue/queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "discard", ids: [id] }) }); await loadQueue(); };

  return <div className="min-h-screen bg-background p-4 text-foreground md:p-6">
    <header className="mb-5 flex flex-wrap items-start justify-between gap-4"><div><div className="text-xs uppercase tracking-[0.22em] text-primary">AM-Core · Unified parameter catalogue</div><div className="mt-1 flex items-center gap-2"><h1 className="text-2xl font-semibold">{t("Каталог параметров AM")}</h1><V3InfoTip content={t("Единый опубликованный набор параметров. Исторические выгрузки Genesis не участвуют в каталоге.")} /></div></div><div className="flex items-center gap-2"><span className={`rounded-md border px-3 py-2 text-xs ${status.indexes_dirty ? "border-amber-500/50 text-amber-300" : "border-emerald-500/30 text-emerald-300"}`}>{t(status.indexes_dirty ? "Индексы устарели — перестроить в конце" : "Индексы актуальны")}</span><button className={inputClass} onClick={() => void refresh()} title={t("Обновить")}><RefreshCw className={`h-4 w-4 ${busy ? "animate-spin" : ""}`} /></button></div></header>
    <nav className="mb-4 flex gap-1 overflow-x-auto rounded-lg border border-white/10 bg-black/20 p-1">{tabs.map(([key, label]) => <button key={key} className={`shrink-0 rounded-md px-3 py-2 text-sm transition ${tab === key ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:bg-white/5 hover:text-foreground"}`} onClick={() => setTab(key)}>{label}{key === "queue" && queue.filter((item) => item.status === "pending" || item.status === "failed").length > 0 ? ` · ${queue.filter((item) => item.status === "pending" || item.status === "failed").length}` : ""}</button>)}</nav>
    {notice && <div className="mb-4 flex items-start justify-between gap-3 rounded-md border border-primary/30 bg-primary/5 px-3 py-2 text-sm"><span>{notice}</span><button onClick={() => setNotice("")} aria-label="Закрыть"><X className="h-4 w-4" /></button></div>}
    {tab === "layer-search" && <AMCatalogueLayerSearch setNotice={setNotice} refresh={refresh} />}
    {(tab === "catalog" || tab === "categories" || tab === "gaps") && <section className="rounded-xl border border-white/10 bg-black/15 p-4">
      <div className="mb-4 flex flex-wrap items-center gap-2"><div className="relative min-w-[220px] flex-1"><Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><input className={`${inputClass} w-full pl-9 pr-9`} placeholder={t("Поиск по имени, описаниям, тегам…")} value={query} onChange={(event) => setQuery(event.target.value)} /><button className="absolute right-2 top-2" aria-label={t("Очистить поиск")} onClick={() => setQuery("")}><X className="h-4 w-4 text-muted-foreground" /></button></div><select className={inputClass} value={typeFilter} onChange={(event) => { setTypeFilter(event.target.value); setPage(1); }}><option value="">{t("Все типы")}</option>{["Range", "Select", "Toggle", "Text", "Array", "String"].map((item) => <option key={item}>{item}</option>)}</select><select className={inputClass} value={category} onChange={(event) => { setCategory(event.target.value); setSubCategory(""); setPage(1); }}><option value="">{t("Все категории")}</option>{categories.map((item) => <option key={item.category}>{item.category}</option>)}</select><select className={inputClass} value={subCategory} onChange={(event) => { setSubCategory(event.target.value); setPage(1); }}><option value="">{t("Все подкатегории")}</option>{(categories.find((item) => item.category === category)?.subcategories ?? categories.flatMap((item) => item.subcategories)).map((item, index) => <option key={`${item.sub_category}-${index}`}>{item.sub_category}</option>)}</select><input className={`${inputClass} w-32`} placeholder={t("Домен")} value={domain} onChange={(event) => { setDomain(event.target.value); setPage(1); }} /><select className={inputClass} value={completeness} onChange={(event) => setCompleteness(event.target.value)}><option value="all">{t("Любая полнота")}</option><option value="complete">{t("Полные")}</option><option value="missing">{t("С пробелами")}</option></select><select className={inputClass} value={presence} onChange={(event) => setPresence(event.target.value)}><option value="all">{t("Категория: все")}</option><option value="has">{t("С категорией")}</option><option value="none">{t("Без категории")}</option></select><button className={`${inputClass} flex items-center gap-1`} onClick={resetFilters}><FilterX className="h-4 w-4" />{t("Сбросить")}</button></div>
      {(category || subCategory || domain || completeness !== "all" || presence !== "all" || typeFilter) && <div className="mb-3 flex flex-wrap gap-2">{category && <button className="rounded-full border border-primary/30 px-2 py-1 text-xs" onClick={() => { setCategory(""); setSubCategory(""); }}>Категория: {category} ×</button>}{subCategory && <button className="rounded-full border border-primary/30 px-2 py-1 text-xs" onClick={() => setSubCategory("")}>Подкатегория: {subCategory} ×</button>}{domain && <button className="rounded-full border border-primary/30 px-2 py-1 text-xs" onClick={() => setDomain("")}>Домен: {domain} ×</button>}{completeness !== "all" && <button className="rounded-full border border-primary/30 px-2 py-1 text-xs" onClick={() => setCompleteness("all")}>Полнота: {completeness === "complete" ? "полные" : "с пробелами"} ×</button>}{presence !== "all" && <button className="rounded-full border border-primary/30 px-2 py-1 text-xs" onClick={() => setPresence("all")}>Категория: {presence === "has" ? "есть" : "нет"} ×</button>}</div>}
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2 text-xs text-muted-foreground"><span>{t("Найдено:")} {total.toLocaleString("ru-RU")} · {t("выбрано:")} {selected.length}</span><div className="flex gap-2"><button className="rounded border border-white/10 px-2 py-1 hover:bg-white/5" onClick={beginAdd}><Plus className="mr-1 inline h-3.5 w-3.5" />{t("Добавить")}</button><button className="rounded border border-white/10 px-2 py-1 hover:bg-white/5" disabled={!selected.length} onClick={() => void stageDelete(selected)}><Trash2 className="mr-1 inline h-3.5 w-3.5" />{t("Удалить выбранные")}</button><button className="rounded border border-white/10 px-2 py-1 hover:bg-white/5" disabled={!selected.length} onClick={() => void exportFile("json", selected)}><Download className="mr-1 inline h-3.5 w-3.5" />{t("Экспорт выбранных")}</button></div></div>
      {tab === "categories" && <div className="mb-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{categories.map((item) => <div key={item.category} className="rounded-lg border border-white/10 p-3"><button className="flex w-full items-center justify-between text-left font-medium hover:text-primary" onClick={() => { setCategory(category === item.category ? "" : item.category); setTab("catalog"); }}><span><FolderTree className="mr-2 inline h-4 w-4" />{item.category}</span><span className="text-xs text-muted-foreground">{item.count}</span></button><div className="mt-2 flex flex-wrap gap-1">{item.subcategories.map((child) => <button key={child.sub_category} onClick={() => { setCategory(item.category); setSubCategory(child.sub_category); setTab("catalog"); }} className="rounded border border-white/10 px-2 py-1 text-xs text-muted-foreground hover:border-primary/40 hover:text-foreground">{child.sub_category} · {child.count}</button>)}</div></div>)}</div>}
      {tab === "gaps" && <div className="mb-4 grid gap-3 md:grid-cols-3"><div className="rounded-lg border border-amber-500/20 p-3"><strong className="text-amber-200">Неполные параметры</strong><div className="mt-1 text-2xl">{gaps.incomplete.length}</div><p className="text-xs text-muted-foreground">Отсутствуют поля схемы или важные метаданные.</p></div><div className="rounded-lg border border-white/10 p-3"><strong>Без категории / подкатегории</strong><div className="mt-1 text-2xl">{gaps.uncategorized.length}</div><p className="text-xs text-muted-foreground">Категория и подкатегория проверяются отдельно.</p></div><div className="rounded-lg border border-white/10 p-3"><strong>Пустые / малые группы</strong><div className="mt-1 text-2xl">{gaps.sparse_categories.length}</div><p className="text-xs text-muted-foreground">Малой считается группа менее 3 элементов.</p></div></div>}
      {tab === "gaps" && <><div className="mb-2 flex flex-wrap items-center gap-2"><span className="text-xs text-muted-foreground">Список:</span><button className={`rounded border px-2 py-1 text-xs ${gapScope === "incomplete" ? "border-primary/60 text-primary" : "border-white/10"}`} onClick={() => setGapScope("incomplete")}>Неполные ({gaps.incomplete.length})</button><button className={`rounded border px-2 py-1 text-xs ${gapScope === "uncategorized" ? "border-primary/60 text-primary" : "border-white/10"}`} onClick={() => setGapScope("uncategorized")}>Без категории / подкатегории ({gaps.uncategorized.length})</button><span className="ml-2 text-xs text-muted-foreground">Сортировать:</span><select className={inputClass} value={gapSort} onChange={(event) => setGapSort(event.target.value)}><option value="technical_name">Имя</option><option value="category">Категория</option><option value="name_ru">Отображаемое имя</option><option value="ui_element">Тип</option></select><button className="ml-auto rounded border border-white/10 px-2 py-1 text-xs" onClick={() => void exportFile("json", filteredGapRows.map((row) => row.technical_name))}>Экспортировать список</button></div><div className="mb-3 flex flex-wrap gap-2">{gaps.sparse_categories.map((node) => <button key={`${node.category}-${node.sub_category}`} className="rounded border border-amber-500/20 px-2 py-1 text-xs text-amber-200 hover:border-amber-400/60" title={`В группе ${node.count}; порог малой группы ${node.sparse_limit}`} onClick={() => { const parameter: Parameter = { technical_name: "", ui_element: "Range", category: node.category, ...(node.sub_category ? { sub_category: node.sub_category } : {}) }; setEditor({ mode: "add", parameter }); setEditorText(JSON.stringify({ technical_name: "", ui_element: "Range", category: node.category, ...(node.sub_category ? { sub_category: node.sub_category } : {}), name_ru: "", description_en: "", description_ru: "", semantic_keywords: [], lyria_prompt_tags: [] }, null, 2)); }}>{node.category}{node.sub_category ? ` / ${node.sub_category}` : ""} · {node.count} · Добавить</button>)}</div></>}
      <div className="max-h-[62vh] overflow-auto rounded-lg border border-white/10"><table className="w-full min-w-[900px] border-collapse text-left text-sm"><thead className="sticky top-0 bg-background"><tr className="border-b border-white/10 text-xs text-muted-foreground"><th className="p-3"><input type="checkbox" checked={rows.length > 0 && selected.length === rows.length} onChange={toggleAll} aria-label={t("Выбрать страницу")} /></th>{[["technical_name", "Technical name"], ["category", "Категория"], ["sub_category", "Подкатегория"], ["ui_element", "Тип"], ["name_ru", "Название"], ["completeness", "Полнота"], ["domain", "Домен"]].map(([field, label]) => <th key={field} className="p-3"><button onClick={() => toggleSort(field)} className="inline-flex items-center gap-1 hover:text-foreground">{label}{sort === field && (direction === "asc" ? <ArrowUp className="h-3 w-3" /> : <ArrowDown className="h-3 w-3" />)}</button></th>)}<th className="p-3">{t("Действия")}</th></tr></thead><tbody>{(tab === "gaps" ? filteredGapRows.slice((page - 1) * pageSize, page * pageSize) : rows).map((row) => <tr key={row.technical_name} className="border-b border-white/5 align-top hover:bg-white/[0.025]"><td className="p-3"><input type="checkbox" checked={selected.includes(row.technical_name)} onChange={() => setSelected((current) => current.includes(row.technical_name) ? current.filter((name) => name !== row.technical_name) : [...current, row.technical_name])} aria-label={`Выбрать ${row.technical_name}`} /></td><td className="p-3 font-mono text-xs text-primary">{row.technical_name}{row.queued && <span className="ml-2 rounded bg-amber-500/10 px-1 text-amber-200">в очереди</span>}<div className="mt-1 max-w-[300px] truncate text-[11px] text-muted-foreground">{row.description_en}</div></td><td className="p-3">{row.category || <span className="text-amber-300">—</span>}</td><td className="p-3">{row.sub_category || <span className="text-amber-300">—</span>}</td><td className="p-3 font-mono text-xs">{row.ui_element || "—"}</td><td className="p-3">{row.name_ru || "—"}</td><td className="p-3"><span className={(row._catalogue?.completeness ?? 0) < 70 ? "text-amber-300" : "text-emerald-300"}>{row._catalogue?.completeness ?? "—"}%</span><div className="max-w-[220px] text-[10px] text-muted-foreground">{row._catalogue?.missing_fields.join(", ")}</div></td><td className="p-3">{row.domain ?? "—"}<div className="text-[10px] text-muted-foreground">{row._catalogue?.source}</div></td><td className="p-3"><div className="flex gap-1"><button className="rounded border border-white/10 px-2 py-1 text-xs hover:border-primary/40" onClick={() => beginEdit(row)}>{t("Править")}</button><button className="rounded border border-white/10 p-1.5 text-muted-foreground hover:text-red-300" onClick={() => void stageDelete([row.technical_name])} aria-label={`Удалить ${row.technical_name}`}><Trash2 className="h-3.5 w-3.5" /></button></div></td></tr>)}</tbody></table>{(tab === "gaps" ? filteredGapRows.length === 0 : rows.length === 0) && <p className="p-8 text-center text-sm text-muted-foreground">{t("Ничего не найдено.")}</p>}</div>
      <div className="mt-3 flex items-center justify-between text-xs text-muted-foreground"><span>Страница {page} из {tab === "gaps" ? Math.max(1, Math.ceil(filteredGapRows.length / pageSize)) : Math.max(1, Math.ceil(total / pageSize))}</span><div className="flex gap-2"><button className="rounded border border-white/10 px-3 py-1.5 disabled:opacity-40" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Назад</button><button className="rounded border border-white/10 px-3 py-1.5 disabled:opacity-40" disabled={page >= Math.ceil((tab === "gaps" ? filteredGapRows.length : total) / pageSize)} onClick={() => setPage((value) => value + 1)}>Дальше</button></div></div>
    </section>}
    {tab === "completeness" && <AMParametersCompletenessPanel selected={selected} setSelected={setSelected} categories={categories.map((item) => item.category)} batchSize={fillBatchSize} setBatchSize={setFillBatchSize} refresh={refresh} setNotice={setNotice} />}
    {tab === "normalization" && <AMParametersNormalizationPanel data={normalization} queueCount={queue.filter((item) => item.status === "pending" || item.status === "failed").length} busy={busy} confidenceThreshold={confidenceThreshold} setConfidenceThreshold={setConfidenceThreshold} batchSize={batchSize} setBatchSize={setBatchSize} autoApply={autoApply} setAutoApply={setAutoApply} forceDomain={forceDomain} setForceDomain={setForceDomain} forceEnrichment={forceEnrichment} setForceEnrichment={setForceEnrichment} run={runNormalization} refresh={() => void loadNormalization()} openQueue={() => setTab("queue")} />}
    {tab === "queue" && <section className="rounded-xl border border-white/10 bg-black/15 p-4"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><div><h2 className="text-lg font-medium">Очередь изменений</h2><p className="text-sm text-muted-foreground">Добавления, обновления и физические удаления вступают в силу только после подтверждённого commit.</p></div><button className="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50" disabled={busy || !queue.some((item) => item.status === "pending" || item.status === "applying" || item.status === "failed")} onClick={() => void commit()}>{busy ? <LoaderCircle className="mr-2 inline h-4 w-4 animate-spin" /> : <Check className="mr-2 inline h-4 w-4" />}{busy ? "Сохраняю…" : "Подтвердить commit"}</button></div><div className="space-y-2">{queue.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/10 p-3"><div className="min-w-[220px] flex-1"><div className="font-mono text-sm">{item.technical_name}</div><div className="mt-1 text-xs text-muted-foreground">{item.operation} · {item.status} · {new Date(item.created_at).toLocaleString("ru-RU")} {item.reason ? `· ${item.reason}` : ""}</div>{item.error && <div className="mt-1 text-xs text-red-300">{item.error}</div>}</div>{item.payload && <button className="rounded border border-white/10 px-2 py-1 text-xs" onClick={() => { setEditor({ mode: "edit", parameter: item.payload!, queueId: item.id }); setEditorText(JSON.stringify(item.payload, null, 2)); }}>Проверить / править</button>}{item.status === "failed" && <button className="rounded border border-amber-500/30 px-2 py-1 text-xs text-amber-200" onClick={async () => { await fetch("/api/am-parameters-catalogue/queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ action: "retry", ids: [item.id] }) }); await loadQueue(); }}>Повторить</button>}<button className="rounded border border-white/10 p-2 text-muted-foreground hover:text-red-300" onClick={() => void discardQueue(item.id)} title="Убрать из очереди"><X className="h-4 w-4" /></button></div>)}</div>{!queue.length && <p className="py-12 text-center text-sm text-muted-foreground">Очередь пуста.</p>}</section>}
    {tab === "exchange" && <section className="grid gap-4 xl:grid-cols-2"><div className="rounded-xl border border-white/10 bg-black/15 p-5"><h2 className="mb-1 text-lg font-medium">Импорт в очередь</h2><p className="mb-4 text-sm text-muted-foreground">JSON, JSONL или ZIP с деревом category/sub_category. Входные записи проверяются по фактическому RuntimeParameterRecord.</p><label className="mb-3 flex items-center gap-2 text-sm text-muted-foreground">Обработка дублей<select className={inputClass} value={duplicateMode} onChange={(event) => setDuplicateMode(event.target.value)}><option value="skip">Пропустить</option><option value="overwrite">Заменить через очередь</option><option value="stage-update">Добавить обновление в очередь</option></select></label><label className="flex cursor-pointer items-center justify-center gap-2 rounded-lg border border-dashed border-primary/40 p-8 text-sm hover:bg-primary/5"><FileUp className="h-5 w-5" />Выбрать файл<input className="sr-only" type="file" accept=".json,.jsonl,.zip,application/json" onChange={(event) => void importFile(event.target.files?.[0])} /></label><div className="mt-3 flex items-start gap-2 text-xs text-muted-foreground"><AlertTriangle className="h-4 w-4 shrink-0 text-amber-300" />Дубли по умолчанию предлагаются как staged update; исходная библиотека не перезаписывается.</div></div><div className="rounded-xl border border-white/10 bg-black/15 p-5"><h2 className="mb-1 text-lg font-medium">Экспорт библиотеки</h2><p className="mb-4 text-sm text-muted-foreground">Экспортируйте текущий фильтр или всё содержимое опубликованной библиотеки.</p><div className="grid gap-2 sm:grid-cols-3">{[["json", "JSON-файл"], ["jsonl", "JSONL"], ["zip", "ZIP по категориям"]].map(([format, label]) => <button key={format} onClick={() => void exportFile(format)} className="rounded-lg border border-white/10 p-4 text-left hover:border-primary/50 hover:bg-primary/5"><Download className="mb-3 h-5 w-5 text-primary" /><div className="font-medium">{label}</div><div className="mt-1 text-xs text-muted-foreground">{format === "zip" ? "Категория → подкатегория" : "С manifest и числом записей"}</div></button>)}</div><div className="mt-4 flex flex-wrap gap-2"><button className="rounded border border-white/10 px-3 py-2 text-sm" onClick={async () => { setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ format: "json", gaps_only: true }) }); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "am-parameters-gaps.json"; link.click(); URL.revokeObjectURL(url); } finally { setBusy(false); } }}>Экспорт пробелов · JSON</button><button className="rounded border border-white/10 px-3 py-2 text-sm" onClick={async () => { setBusy(true); try { const response = await fetch("/api/am-parameters-catalogue/export", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ format: "zip", gaps_only: true }) }); const blob = await response.blob(); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = "am-parameters-gaps.zip"; link.click(); URL.revokeObjectURL(url); } finally { setBusy(false); } }}>Экспорт пробелов · ZIP</button></div><button className="mt-5 rounded border border-white/10 px-3 py-2 text-sm" onClick={() => setTab("queue")}><Upload className="mr-2 inline h-4 w-4" />Открыть очередь</button></div></section>}
    {tab === "status" && <section className="rounded-xl border border-white/10 bg-black/15 p-5"><h2 className="text-lg font-medium">Состояние опубликованной библиотеки и индексов</h2><p className="mt-1 text-sm text-muted-foreground">Исторические снимки Genesis хранятся отдельно и не участвуют в каталоге. Commit каталога не перемещает и не удаляет файлы inbox.</p><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[["Состояние", status.indexes_dirty ? "Требуется rebuild" : "Актуально"], ["Ожидают commit", String(status.pending_count ?? 0)], ["Последний commit", status.last_commit_at ? new Date(String(status.last_commit_at)).toLocaleString("ru-RU") : "—"], ["Revision", String(status.revision ?? "—").slice(0, 16)]].map(([label, value]) => <div key={label} className="rounded-lg border border-white/10 p-3"><div className="text-xs text-muted-foreground">{label}</div><div className="mt-1 break-all font-medium">{value}</div></div>)}</div><div className="mt-4 rounded-lg border border-white/10 p-4"><div className="flex items-center gap-2 font-medium">{(status.job as { running?: boolean })?.running ? <LoaderCircle className="h-4 w-4 animate-spin text-primary" /> : <Check className="h-4 w-4 text-emerald-300" />}Пересборка: {(status.job as { step?: string })?.step ?? "не запускалась"}</div>{(status.job as { total?: number; current?: number })?.total ? <div className="mt-2 text-xs text-muted-foreground">{String((status.job as { current: number }).current)} / {String((status.job as { total: number }).total)}</div> : null}{(status.job as { error?: string })?.error && <p className="mt-2 text-sm text-red-300">{String((status.job as { error: string }).error)}</p>}<pre className="mt-3 max-h-56 overflow-auto whitespace-pre-wrap rounded bg-black/30 p-3 text-[11px] text-muted-foreground">{((status.job as { logs?: string[] })?.logs ?? []).join("\n") || "Журнал появится после запуска."}</pre></div><div className="mt-4 flex flex-wrap gap-2"><button className="rounded border border-white/10 px-3 py-2 text-sm" onClick={() => void loadStatus()}><RefreshCw className="mr-2 inline h-4 w-4" />Обновить состояние</button><button className="rounded border border-primary/40 px-3 py-2 text-sm hover:bg-primary/10 disabled:opacity-50" disabled={(status.job as { running?: boolean })?.running || busy || !status.indexes_dirty} onClick={() => void rebuildIndexes()}><RefreshCw className="mr-2 inline h-4 w-4" />Пересобрать индексы</button></div></section>}
    {editor && <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 p-4" role="dialog" aria-modal="true" aria-label="Редактор параметра"><div className="flex max-h-[90vh] w-full max-w-3xl flex-col rounded-xl border border-white/15 bg-background shadow-2xl"><div className="flex items-center justify-between border-b border-white/10 p-4"><div><h2 className="font-medium">{editor.mode === "add" ? "Новый параметр" : `Редактирование: ${editor.parameter.technical_name}`}</h2><p className="text-xs text-muted-foreground">Схема открыта для дополнительных полей: существующие данные сохраняются.</p></div><button onClick={() => setEditor(null)} aria-label="Закрыть"><X className="h-5 w-5" /></button></div><textarea className="m-4 min-h-[50vh] flex-1 resize-y rounded-lg border border-white/10 bg-black/30 p-4 font-mono text-xs outline-none focus:border-primary/50" value={editorText} onChange={(event) => setEditorText(event.target.value)} /><div className="flex justify-end gap-2 border-t border-white/10 p-4"><button className="rounded border border-white/10 px-4 py-2 text-sm" onClick={() => setEditor(null)}>Отмена</button><button className="rounded bg-primary px-4 py-2 text-sm text-primary-foreground" disabled={busy} onClick={() => void submitEdit()}>Сохранить в очередь</button></div></div></div>}
  </div>;
}


function AMParametersCompletenessPanel(props: { selected: string[]; setSelected: (updater: (current: string[]) => string[]) => void; categories: string[]; batchSize: number; setBatchSize: (value: number) => void; refresh: () => Promise<void>; setNotice: (value: string) => void }) {
  const [data, setData] = useState<{ total: number; complete: number; completeness: number; forbidden_count: number; missing_counts: Record<string, number>; parameters: CompletionRow[] } | null>(null);
  const [type, setType] = useState(""); const [category, setCategory] = useState(""); const [missing, setMissing] = useState(""); const [provider, setProvider] = useState("freellmapi"); const [confidence, setConfidence] = useState(0.6); const [running, setRunning] = useState(false); const [stopPending, setStopPending] = useState(false); const stopRequested = useRef(false); const [retry, setRetry] = useState<Array<{ technical_name: string; attempts: number; status: string; error: string }>>([]);
  const load = useCallback(async () => { const query = new URLSearchParams(); if (type) query.set("type", type); if (category) query.set("category", category); if (missing) query.set("missing_field", missing); const response = await fetch(`/api/am-parameters-catalogue/completeness?${query}`); const result = await response.json(); if (response.ok) setData(result); const retryResponse = await fetch("/api/am-parameters-catalogue/completeness/retry-queue"); const retryData = await retryResponse.json(); if (retryResponse.ok) setRetry(retryData.items); }, [type, category, missing]);
  useEffect(() => { const timer = window.setTimeout(() => { void load(); }, 0); return () => window.clearTimeout(timer); }, [load]);
  const filteredNames = data?.parameters.map((row) => row.technical_name) ?? [];
  const toggleAll = () => props.setSelected((current) => filteredNames.length > 0 && filteredNames.every((name) => current.includes(name)) ? current.filter((name) => !filteredNames.includes(name)) : [...new Set([...current, ...filteredNames])]);
  const run = async (names: string[] | undefined, retryOnly = false) => { stopRequested.current = false; setStopPending(false); setRunning(true); try { if (retryOnly) { const permanent = retry.filter((item) => item.status === "failed_permanent").map((item) => item.technical_name); if (permanent.length) await fetch("/api/am-parameters-catalogue/completeness/retry-queue", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ confirmed: true, technical_names: permanent }) }); await load(); } const targets = retryOnly ? retry.filter((item) => item.status === "retry" || item.status === "failed_permanent").map((item) => item.technical_name) : names ?? filteredNames; let processed = 0; let improved = 0; let failures = 0; for (let offset = 0; offset < targets.length && !stopRequested.current; offset += props.batchSize) { const batch = targets.slice(offset, offset + props.batchSize); const response = await fetch("/api/am-parameters-catalogue/completeness/run", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ provider, technical_names: batch, batch_size: props.batchSize, confidence_threshold: confidence, retry: retryOnly }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); processed += Number(result.attempted ?? batch.length); improved += Number(result.succeeded ?? 0); failures += Number(result.failed?.length ?? 0); props.setNotice(`${stopRequested.current ? "Остановка после текущего пакета. " : ""}Полнота: ${Math.min(offset + batch.length, targets.length)} / ${targets.length} · улучшено ${improved} · ошибок ${failures}.`); } await load(); await props.refresh(); props.setNotice(`${stopRequested.current ? "Заполнение остановлено после текущего пакета. " : "Полнота: "}${processed} обработано · ${improved} улучшено · ошибок ${failures}.`); } catch (error) { props.setNotice(error instanceof Error ? error.message : "Ошибка заполнения."); } finally { setRunning(false); } };
  const strip = async () => { setRunning(true); try { const response = await fetch("/api/am-parameters-catalogue/schema/strip-provenance", { method: "POST" }); const result = await response.json(); if (!response.ok) throw new Error(result.error); props.setNotice(`Очищено ${result.changed} записей. Резервная копия: ${result.backup ?? "не требовалась"}.`); await load(); await props.refresh(); } catch (error) { props.setNotice(error instanceof Error ? error.message : "Ошибка очистки схемы."); } finally { setRunning(false); } };
  return <section className="space-y-4 rounded-xl border border-white/10 bg-black/15 p-4"><div><h2 className="text-lg font-medium">Полнота каталога</h2><p className="text-sm text-muted-foreground">Type-aware проверка по FLOWMUSIC_COLLECTION_PROMPT_V1. Заполнение меняет только неполные поля; индексы не перестраиваются.</p></div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[["Параметры", data?.total], ["Полные", data?.complete], ["Полнота", data ? `${data.completeness}%` : "—"], ["Provenance-ключи", data?.forbidden_count]].map(([label, value]) => <div key={String(label)} className="rounded-lg border border-white/10 p-3"><div className="text-xs text-muted-foreground">{label}</div><div className="mt-1 text-xl font-semibold">{value ?? "—"}</div></div>)}</div><div className="flex flex-wrap gap-2"><select className={inputClass} value={type} onChange={(event) => setType(event.target.value)}><option value="">Все типы</option>{["Range", "Select", "Toggle", "Text", "Array", "String"].map((item) => <option key={item}>{item}</option>)}</select><select className={inputClass} value={category} onChange={(event) => setCategory(event.target.value)}><option value="">Все категории</option>{props.categories.map((item) => <option key={item}>{item}</option>)}</select><select className={inputClass} value={missing} onChange={(event) => setMissing(event.target.value)}><option value="">Все поля</option>{Object.entries(data?.missing_counts ?? {}).sort((a,b) => b[1]-a[1]).map(([field,count]) => <option key={field} value={field}>{field} · {count}</option>)}</select><select className={inputClass} value={provider} onChange={(event) => setProvider(event.target.value)}><option value="freellmapi">FreeLLMAPI</option><option value="ollama">Ollama</option></select><label className="flex items-center gap-2 text-xs">Уверенность<input className={inputClass} type="number" min={0} max={1} step={0.05} value={confidence} onChange={(event) => setConfidence(Number(event.target.value))} /></label><label className="flex items-center gap-2 text-xs">Batch<input className={inputClass} type="number" min={1} max={50} value={props.batchSize} onChange={(event) => props.setBatchSize(Number(event.target.value))} /></label></div><div className="flex flex-wrap gap-2"><button className="rounded border border-white/10 px-3 py-2 text-sm" disabled={running} onClick={toggleAll}>Выбрать все фильтрованные ({filteredNames.length})</button><button className="rounded bg-primary px-3 py-2 text-sm text-primary-foreground disabled:opacity-50" disabled={running} onClick={() => void run(props.selected.length ? props.selected : undefined)}>Заполнить {props.selected.length ? `выбранные (${props.selected.length})` : "все неполные"}</button>{running && <><span role="status" className="self-center text-xs text-amber-200">{stopPending ? "Остановится после текущего пакета…" : "Выполняется текущий пакет…"}</span><button className="rounded border border-red-500/40 px-3 py-2 text-sm text-red-200" onClick={() => { stopRequested.current = true; setStopPending(true); props.setNotice("Остановка запрошена; текущий пакет завершится перед остановкой."); }}>Стоп</button></>}<button className="rounded border border-amber-500/30 px-3 py-2 text-sm text-amber-200 disabled:opacity-50" disabled={running} onClick={() => void strip()}>Очистить provenance</button><button className="rounded border border-white/10 px-3 py-2 text-sm disabled:opacity-50" disabled={running || !retry.length} onClick={() => void run(undefined, true)}>Повторить ошибки ({retry.length})</button><button className="rounded border border-white/10 px-3 py-2 text-sm" onClick={() => void load()}>Обновить</button></div><div className="max-h-[58vh] overflow-auto rounded-lg border border-white/10"><table className="w-full min-w-[900px] text-left text-xs"><thead className="sticky top-0 bg-background"><tr className="border-b border-white/10 text-muted-foreground"><th className="p-2"><input type="checkbox" checked={filteredNames.length > 0 && filteredNames.every((name) => props.selected.includes(name))} onChange={toggleAll} aria-label="Выбрать отфильтрованные" /></th><th className="p-2">Тип</th><th className="p-2">Technical name</th><th className="p-2">Название</th><th className="p-2">Категория</th><th className="p-2">Пробелы</th><th className="p-2">Полнота</th></tr></thead><tbody>{(data?.parameters ?? []).map((row) => <tr key={row.technical_name} className="border-b border-white/5"><td className="p-2"><input type="checkbox" checked={props.selected.includes(row.technical_name)} onChange={() => props.setSelected((current) => current.includes(row.technical_name) ? current.filter((name) => name !== row.technical_name) : [...current, row.technical_name])} /></td><td className="p-2">{row.ui_element}</td><td className="p-2 font-mono text-primary">{row.technical_name}</td><td className="p-2">{row.name_ru || "—"}</td><td className="p-2">{row.category || "—"}</td><td className="p-2">{row._completion.missing_fields.join(", ")}</td><td className="p-2">{row._completion.completeness}%</td></tr>)}</tbody></table></div><div className="rounded-lg border border-white/10 p-3"><div className="mb-2 text-sm font-medium">Retry queue · max 3 attempts</div>{retry.map((item) => <div key={item.technical_name} className="border-b border-white/5 py-1 text-xs"><span className="font-mono">{item.technical_name}</span> · {item.status} · {item.attempts}/3 · {item.error}</div>)}{!retry.length && <div className="text-xs text-muted-foreground">Ошибок нет.</div>}</div></section>;
}
